INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A circulação pulmonar é essencial para a hematose. Qual destas estruturas transporta o sangue desoxigenado do coração para os pulmões e qual a sua relação anatômica com os brônquios principais?","options":{"a":"Veias pulmonares; situam-se anteriormente aos brônquios.","b":"Artéria pulmonar; situa-se superiormente ao brônquio esquerdo e anteriormente ao brônquio direito.","c":"Artéria aorta; situa-se posterior aos brônquios.","d":"Veia cava superior; situa-se medial aos brônquios.","e":"Artérias bronquiais; situam-se inferiormente aos brônquios."},"answer":"b","rationale":"O tronco pulmonar divide-se em artérias pulmonares direita e esquerda. A artéria pulmonar esquerda é superior ao brônquio principal esquerdo, enquanto a direita é anterior ao brônquio principal direito no hilo pulmonar.","option_rationales":{"a":"Errada. Veias pulmonares transportam sangue oxigenado.","b":"Correta. Anatomia hilar pulmonar.","c":"Errada. A aorta não vai para os pulmões para hematose.","d":"Errada. Drena sangue para o átrio direito.","e":"Errada. Artérias bronquiais nutrem o parênquima, mas o transporte principal para hematose é via artéria pulmonar."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Pulmão"]}', '4cabef7886f8c5ac2915807be0fc84f4', 0, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Vascularização do Coração'' é garantida pelas artérias coronárias. Qual ramo da artéria coronária esquerda é frequentemente chamado de ''artéria da morte súbita'' por irrigar a maior parte do septo interventricular e a parede anterior do ventrículo esquerdo?","options":{"a":"Artéria circunflexa.","b":"Artéria marginal esquerda.","c":"Artéria interventricular anterior (descendente anterior).","d":"Artéria coronária direita.","e":"Artéria do nó sinoatrial."},"answer":"c","rationale":"A artéria interventricular anterior (DA) é o ramo mais crítico para a função ventricular esquerda global.","option_rationales":{"a":"Errada. Irriga a parede lateral.","b":"Errada.","c":"Correta. Anatomia coronariana aplicada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Cardiologia"]}', '961b4cd8202ba9e98d5af99a93a95600', 1, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"As ''Veias do Coração'' drenam para o átrio direito. Qual estrutura venosa recebe a maior parte do sangue das veias cardíacas (magna, média e parva) antes de desembocar no átrio?","options":{"a":"Veia cava inferior.","b":"Veia cava superior.","c":"Seio coronário.","d":"Veias pulmonares.","e":"Veias cardíacas anteriores."},"answer":"c","rationale":"O seio coronário localiza-se no sulco atrioventricular posterior e drena para o átrio direito.","option_rationales":{"a":"Errada. Drena o corpo inferior.","b":"Errada. Drena o corpo superior.","c":"Correta. Drenagem venosa cardíaca.","d":"Errada.","e":"Errada. Estas drenam diretamente para o átrio direito, sem passar pelo seio."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Cardiologia"]}', 'a29850df9df8876489b15c271904d959', 2, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O ''Arco Aórtico'' emite três ramos principais em sua configuração padrão. Qual destes vasos é o primeiro ramo a se originar e qual a sua divisão subsequente?","options":{"a":"Artéria carótida comum esquerda; divide-se em interna e externa.","b":"Artéria subclávia esquerda; continua como artéria axilar.","c":"Tronco braquiocefálico; divide-se em carótida comum direita e subclávia direita.","d":"Artéria coronária direita; irriga o átrio direito.","e":"Tronco celíaco; divide-se em gástrica, esplênica e hepática."},"answer":"c","rationale":"O tronco braquiocefálico é o primeiro e maior ramo do arco aórtico no lado direito.","option_rationales":{"a":"Errada. É o segundo ramo.","b":"Errada. É o terceiro ramo.","c":"Correta. Anatomia dos vasos da base.","d":"Errada. Artérias coronárias saem da aorta ascendente.","e":"Errada. Ramo da aorta abdominal."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Grandes Vasos"]}', '554c2ac2f50c503c565eaf8e3c4d26cb', 3, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Carótida Interna'' possui um trajeto complexo. Onde se localiza o ''Sifão Carotídeo'', região sujeita à formação de aterosclerose e aneurismas?","options":{"a":"No pescoço, antes de entrar no canal carótico.","b":"Dentro do seio cavernoso, após passar pelo canal carótico.","c":"Na origem do tronco braquiocefálico.","d":"Após a emergência da artéria oftálmica.","e":"No forame magno."},"answer":"b","rationale":"O sifão carotídeo é a curvatura em ''S'' que a carótida interna faz dentro do seio cavernoso.","option_rationales":{"a":"Errada.","b":"Correta. Neuroanatomia vascular.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Neuroanatomia"]}', 'a3e4258af29b479768c256fce5c9a9b1', 4, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Subclávia'' torna-se ''Artéria Axilar'' ao cruzar qual limite anatômico específico?","options":{"a":"Borda lateral da primeira costela.","b":"Borda inferior do músculo redondo maior.","c":"Clavícula.","d":"Músculo peitoral maior.","e":"Processo coracoide."},"answer":"a","rationale":"A transição de subclávia para axilar ocorre na borda lateral da 1ª costela.","option_rationales":{"a":"Correta. Topografia vascular de membros superiores.","b":"Errada. Limite entre axilar e braquial.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Superior"]}', 'da6240b1cf2ad14468258655b91f4aad', 5, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"Qual artéria do membro superior é utilizada rotineiramente para a aferição da pressão arterial e onde ela se localiza em relação ao músculo bíceps braquial?","options":{"a":"Artéria radial; lateral ao tendão do bíceps.","b":"Artéria braquial; no sulco bicipital medial.","c":"Artéria ulnar; profunda ao pronador redondo.","d":"Artéria axilar; no ápice da axila.","e":"Artéria braquial profunda; posterior ao úmero."},"answer":"b","rationale":"A artéria braquial corre medialmente ao bíceps no braço.","option_rationales":{"a":"Errada. Usada para pulso, mas pressão é braquial.","b":"Correta. Anatomia aplicada ao exame físico.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Superior"]}', '12fb9bbc658b4acd39b124f59c78028f', 6, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O ''Arco Palmar Superficial'' é alimentado predominantemente por qual artéria?","options":{"a":"Artéria radial.","b":"Artéria ulnar.","c":"Artéria interóssea anterior.","d":"Artéria braquial profunda.","e":"Artéria mediana."},"answer":"b","rationale":"A artéria ulnar forma o arco superficial, enquanto a radial forma o arco profundo.","option_rationales":{"a":"Errada. Forma o arco profundo.","b":"Correta. Vascularização da mão.","c":"Errada.","d":"Errada.","e":"Errada. Atrofia na maioria dos adultos."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Superior"]}', 'b1e436076d7f1c9e30ecf2960738d425', 7, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Aorta Abdominal'' emite ramos viscerais ímpares. Qual destes vasos irriga o intestino primitivo médio (do duodeno distal ao terço distal do cólon transverso)?","options":{"a":"Tronco celíaco.","b":"Artéria mesentérica superior.","c":"Artéria mesentérica inferior.","d":"Artérias renais.","e":"Artérias gonadais."},"answer":"b","rationale":"Mesentérica superior = Intestino médio. Tronco celíaco = Intestino anterior. Mesentérica inferior = Intestino posterior.","option_rationales":{"a":"Errada. Irriga estômago, fígado, baço.","b":"Correta. Vascularização gastrointestinal.","c":"Errada. Irriga do cólon distal ao reto.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Abdome"]}', 'ca219c4117ad62428c64b1c3b64514da', 8, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Veia Porta do Fígado'' é formada pela junção de quais veias principais?","options":{"a":"Veias hepáticas e veia cava inferior.","b":"Veia mesentérica superior e veia esplênica.","c":"Veia mesentérica superior e veia inferior.","d":"Veia gástrica e veia renal.","e":"Veia esplênica e veia gástrica curta."},"answer":"b","rationale":"A veia mesentérica superior une-se à esplênica (que geralmente já recebeu a mesentérica inferior) atrás do colo do pâncreas.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia do sistema porta-hepático.","c":"Errada. Faltou a esplênica.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Fígado"]}', '1e2bf0bc0937004dc4caed1accaeb3d1', 9, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"Em casos de hipertensão portal, o sangue busca vias colaterais. Qual o local de anastomose porto-sistêmica que leva à formação de ''Varizes Esofágicas''?","options":{"a":"Veias gástricas curtas e veia esplênica.","b":"Veia gástrica esquerda (coronária estomáquica) e veias esofágicas (sistema ázigo/veia cava superior).","c":"Veias paraumbilicais e veias epigástricas.","d":"Veias retais superiores e veias retais inferiores.","e":"Veias retroperitoneais (de Retzius)."},"answer":"b","rationale":"A comunicação entre a veia gástrica esquerda (porta) e as veias esofágicas (sistêmica) é o sítio mais importante clinicamente.","option_rationales":{"a":"Errada. Ambas pertencem ao sistema porta.","b":"Correta. Anatomia clínica da cirrose/portal.","c":"Errada. Causa ''cabeça de medusa''.","d":"Errada. Causa hemorroidas.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Clínica"]}', '7918c84c726e8213b9911651d6856e8d', 10, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Ilíaca Interna'' é o principal vaso da pelve. Qual de seus ramos irriga a face medial da coxa e atravessa um canal no osso púbis?","options":{"a":"Artéria glútea superior.","b":"Artéria obturatória.","c":"Artéria pudenda interna.","d":"Artéria vesical inferior.","e":"Artéria iliolombar."},"answer":"b","rationale":"A artéria obturatória sai da pelve pelo forame (canal) obturado.","option_rationales":{"a":"Errada.","b":"Correta. Vascularização pélvica.","c":"Errada. Irriga períneo.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Pelve"]}', '56478669522049502d4ff754c3ce87e2', 11, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Femoral'' entra no canal do adutor (canal de Hunter). Após atravessar o hiato do adutor, como ela passa a ser chamada?","options":{"a":"Artéria femoral profunda.","b":"Artéria poplítea.","c":"Artéria tibial anterior.","d":"Artéria fibular.","e":"Artéria descendente do joelho."},"answer":"b","rationale":"A mudança de nome ocorre na transição da face anterior para a posterior (fossa poplítea).","option_rationales":{"a":"Errada. É um ramo da femoral comum.","b":"Correta. Topografia vascular do membro inferior.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Inferior"]}', 'ceec6f37a23857428ab8a6c2ba25dd86', 12, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O pulso da ''Artéria Tibial Posterior'' deve ser pesquisado em qual localização anatômica específica?","options":{"a":"Dorso do pé, lateral ao tendão do extensor longo do hálux.","b":"Atrás do maléolo medial, no túnel do tarso.","c":"Atrás do maléolo lateral.","d":"Na face anterior do tornozelo.","e":"No centro da fossa poplítea."},"answer":"b","rationale":"O pulso tibial posterior é essencial na avaliação de doença arterial periférica.","option_rationales":{"a":"Errada. Local da artéria dorsal do pé (pediosa).","b":"Correta. Semiótica vascular.","c":"Errada.","d":"Errada.","e":"Errada. Local do pulso poplíteo."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Exame Físico"]}', '48d1b24aae826ef0ea9a226210f1d5d9', 13, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Grande Veia Safena'' (safena magna) é frequentemente utilizada em cirurgias de revascularização miocárdica. Onde ela se origina e onde ela desemboca?","options":{"a":"Origina-se atrás do maléolo lateral; desemboca na veia poplítea.","b":"Origina-se à frente do maléolo medial; desemboca na veia femoral no hiato safeno.","c":"Origina-se no dorso do pé; desemboca na veia ilíaca externa.","d":"Origina-se na face lateral da perna; desemboca na veia profunda da coxa.","e":"Origina-se no joelho; desemboca na veia cava inferior."},"answer":"b","rationale":"A safena magna corre medialmente ao longo de todo o membro inferior.","option_rationales":{"a":"Errada. Descrição da safena parva.","b":"Correta. Anatomia venosa superficial.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Cirurgia Vascular"]}', 'ecbe4055a9b1ff080b561507ac86151e', 14, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Veia Cava Superior'' (VCS) é formada pela união das veias braquiocefálicas. Qual estrutura venosa importante desemboca na VCS imediatamente antes dela entrar no pericárdio, drenando o tórax?","options":{"a":"Veia jugular interna.","b":"Veia subclávia.","c":"Veia ázigo.","d":"Veia hemiázigo.","e":"Veia torácica interna."},"answer":"c","rationale":"A veia ázigo faz o arco sobre o brônquio principal direito para entrar na VCS.","option_rationales":{"a":"Errada. Forma a braquiocefálica.","b":"Errada. Forma a braquiocefálica.","c":"Correta. Drenagem venosa do tronco.","d":"Errada. Drena no sistema ázigo à esquerda.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Tórax"]}', '0d4f1c04fd1b205c612e197d829e6524', 15, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Renal'' direita tem uma relação anatômica peculiar com a veia cava inferior (VCI). Como elas se posicionam?","options":{"a":"A artéria renal direita passa anteriormente à VCI.","b":"A artéria renal direita passa posteriormente à VCI.","c":"A artéria renal direita situa-se superior à VCI.","d":"Elas não cruzam uma a outra.","e":"A VCI está à esquerda da artéria aorta."},"answer":"b","rationale":"Como a aorta está à esquerda e a VCI à direita, a artéria renal direita deve cruzar atrás da VCI.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia vascular retroperitoneal.","c":"Errada.","d":"Errada.","e":"Errada. A VCI está à direita."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Abdome"]}', 'd71645436552351ba16c1982618ec64b', 16, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O ''Duto Arterioso'' é uma comunicação funcional no feto. Após o nascimento, ele se oblitera e torna-se qual estrutura anatômica?","options":{"a":"Ligamento venoso.","b":"Ligamento arterioso.","c":"Ligamento falciforme.","d":"Fossa oval.","e":"Uráco."},"answer":"b","rationale":"O duto arterioso ligava a pulmão esquerda à aorta.","option_rationales":{"a":"Errada. Remanescente do ducto venoso.","b":"Correta. Anatomia fetal/neonatal.","c":"Errada.","d":"Errada. Remanescente do forame oval no coração.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Perinatologia"]}', '7efb1005c8b41a79845e312bab63ee67', 17, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Veia Renal Esquerda'' é notavelmente mais longa que a direita. Qual estrutura arterial cruza ANTERIORMENTE à veia renal esquerda, podendo comprimi-la (Fenômeno de Nutcracker)?","options":{"a":"Tronco celíaco.","b":"Artéria mesentérica superior.","c":"Artéria mesentérica inferior.","d":"Artéria ilíaca comum.","e":"Aorta descendente."},"answer":"b","rationale":"A veia renal esquerda passa entre a aorta e a artéria mesentérica superior.","option_rationales":{"a":"Errada. Está acima.","b":"Correta. Síndromes compressivas vasculares.","c":"Errada. Está abaixo.","d":"Errada.","e":"Errada. A aorta está posterior à veia."},"difficulty":"Difícil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Abdome"]}', '6662dda84f248dc45d219fb66c1d4164', 18, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O ''Tronco Celíaco'' emite três ramos clássicos. Qual deles fornece irrigação para o baço e partes do pâncreas?","options":{"a":"Artéria gástrica esquerda.","b":"Artéria hepática comum.","c":"Artéria esplênica.","d":"Artéria gastroduodenal.","e":"Artéria cística."},"answer":"c","rationale":"A esplênica é o maior ramo do tronco celíaco e tem trajeto tortuoso superior ao pâncreas.","option_rationales":{"a":"Errada. Irriga curvatura menor do estômago.","b":"Errada.","c":"Correta. Vascularização do abdome superior.","d":"Errada. Ramo da hepática comum.","e":"Errada. Ramo da hepática direita."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Digestório"]}', 'e24c49ba9b7724095e94f53f7afec512', 19, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"As ''Artérias Intercostais Posteriores'' originam-se predominantemente de onde?","options":{"a":"Artéria torácica interna.","b":"Aorta torácica.","c":"Artérias subclávias.","d":"Artéria axilar.","e":"Arco da aorta."},"answer":"b","rationale":"A aorta torácica fornece as intercostais posteriores para os espaços 3 a 11.","option_rationales":{"a":"Errada. Fornece as intercostais anteriores.","b":"Correta. Vascularização da parede torácica.","c":"Errada. Fornecem apenas os dois primeiros espaços via tronco costocervical.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Tórax"]}', 'd45a7be37bd7740d31545c38cf537b92', 20, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"Qual o principal vaso responsável pela drenagem linfática do lado DIREITO da cabeça, pescoço e membro superior?","options":{"a":"Ducto torácico.","b":"Ducto linfático direito.","c":"Cisterna do quilo.","d":"Veia ázigo.","e":"Tronco lombar."},"answer":"b","rationale":"O ducto linfático direito drena o quadrante superior direito; o ducto torácico drena o restante do corpo.","option_rationales":{"a":"Errada. Drena todo o lado esquerdo e metade inferior do corpo.","b":"Correta. Sistema linfático.","c":"Errada. Início do ducto torácico no abdome.","d":"Errada. Sistema venoso.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Linfático"]}', 'f1bddf8038bcc57d31d280dfafcf0665', 21, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Maxilar'', importante na odontologia e cirurgia bucomaxilofacial, é um dos ramos terminais de qual artéria?","options":{"a":"Artéria carótida interna.","b":"Artéria carótida externa.","c":"Artéria facial.","d":"Artéria carótida comum.","e":"Artéria temporal superficial."},"answer":"b","rationale":"A carótida externa termina dividindo-se em maxilar e temporal superficial.","option_rationales":{"a":"Errada.","b":"Correta. Vascularização da face.","c":"Errada. É um ramo colateral.","d":"Errada.","e":"Errada. É o outro ramo terminal."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Face"]}', '5ec179ca2c96b2ca29b2536127dc76db', 22, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Várzea'' renal... Perdão, a vascularização renal. A ''Artéria Renal'' emite ramos segmentares. Quantos segmentos arteriais renais funcionais são descritos classicamente?","options":{"a":"2 segmentos.","b":"5 segmentos.","c":"10 segmentos.","d":"1 segmento (irrigação terminal).","e":"Nenhum; a irrigação é difusa."},"answer":"b","rationale":"Os segmentos (superior, anterosuperior, anteroinferior, inferior e posterior) são a base para nefrectomias parciais.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia cirúrgica renal.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Urologia"]}', '9f153c855612dc1b5ac97259f8718913', 23, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"Qual a principal veia que drena a face lateral da mão e do antebraço, correndo no sulco deltopeitoral?","options":{"a":"Veia basílica.","b":"Veia cefálica.","c":"Veia mediana do cotovelo.","d":"Veia axilar.","e":"Veia braquial."},"answer":"b","rationale":"A veia cefálica é lateral; a basílica é medial. A cefálica desemboca na veia axilar no triângulo deltopeitoral.","option_rationales":{"a":"Errada. Corre no lado medial.","b":"Correta. Anatomia venosa superficial.","c":"Errada. Comunica as duas no cotovelo.","d":"Errada. É veia profunda.","e":"Errada. É veia profunda."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Superior"]}', '4232cbe2abf6de86107d5e5c9060e7f9', 24, 'draft');